import React from 'react';
import { Link } from 'react-scroll';
import styles from './Home.module.css'; // Importing the CSS module
import profilePic from '/src/assets/images/profilePic.jpg'; // Make sure the path is correct


export const Home = () => {
  return (
    <div id="home" className={styles.homeSection}>
      <img src={profilePic} alt="Tanaya Siddiqui" className={styles.profilePic} />
      <div className={styles.contentBox}>
        <h1>Tanaya Siddiqui</h1>
        <h2>Front-end Developer</h2>
        <p>Developer with a focus on web development and data analysis. Skilled in Python, C, JS, HTML, CSS, React, learning C++ and Unreal Engine.</p>
        <Link to="about" className={styles.aboutLink} smooth={true} duration={500}>Go to About</Link>
      </div>
    </div>
  );
};

export default Home;
